import React, { useEffect, useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";

export const Navigation = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(!!localStorage.getItem("token"));
  const [avatar, setAvatar] = useState('');
  const [dropdownVisible, setDropdownVisible] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();

  // Keep `ownerId` state updated in real time
  const [ownerId, setOwnerId] = useState(localStorage.getItem("ownerId") || null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);
    setOwnerId(localStorage.getItem("ownerId"));

    const ownerData = localStorage.getItem("owner");
    if (ownerData) {
      const owner = JSON.parse(ownerData);
      setAvatar(owner.avatar);
    }

    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownVisible(false);
      }
    };

    window.addEventListener("click", handleClickOutside);
    return () => {
      window.removeEventListener("click", handleClickOutside);
    };
  }, []); // Run only once on mount

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    localStorage.removeItem("role");
    localStorage.removeItem("clinicId");

    // Update state immediately
    setIsLoggedIn(false);
    setOwnerId(null); // Immediately hide profile
    setAvatar('');

    // Navigate to login page
    navigate('/login');
  };

  const closeNavbar = () => {
    const navbarCollapse = document.getElementById("bs-example-navbar-collapse-1");
    if (navbarCollapse) {
      navbarCollapse.classList.remove("in");
    }
  };

  const handleProfileClick = () => {
    if (ownerId) {
      navigate(`/profile?id=${ownerId}`);
    }
  };

  return (
    <nav id="menu" className="navbar navbar-default" style={{ backgroundColor: 'rgba(255, 255, 255, 0.71)', position: 'fixed', width: '100%', zIndex: 1000, top: '0px' }}>
      <div className="container">
        <div className="navbar-header">
          <button type="button" className="navbar-toggle collapsed" data-toggle="collapse" data-target="#bs-example-navbar-collapse-1">
            <span className="sr-only">Toggle navigation</span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
          </button>
          <a className="navbar-brand page-scroll" href="/home">
            <img src={require('../assets/Logo.png')} alt="Petopia Logo" style={{ margin: '-20px', height: '60px' }} />
          </a>
        </div>

        <div className="collapse navbar-collapse" id="bs-example-navbar-collapse-1">
          <ul className="nav navbar-nav navbar-right">
            {isLoggedIn ? (
              <>
                <li className="navbar-home">
                  <a onClick={() => { navigate('/home'); closeNavbar(); }} style={{ color: 'black', fontWeight: "bold" }}>
                    Home
                  </a>
                </li>
                {ownerId && (
                  <li>
                    <a onClick={() => { handleProfileClick(); closeNavbar(); }} style={{ color: 'black', fontWeight: "bold" }}>Profile</a>
                  </li>
                )}
                <li>
                  <a onClick={() => { handleLogout(); closeNavbar(); }} style={{ color: 'black', fontWeight: "bold" }}>Logout</a>
                </li>
              </>
            ) : (
              <>
                <li>
                  <a href="/#header" className="page-scroll" style={{ color: 'black', fontWeight: "bold" }} onClick={closeNavbar}>
                    Home
                  </a>
                </li>
                <li>
                  <a onClick={() => { navigate('/login'); closeNavbar(); }} style={{ color: 'black', fontWeight: "bold", cursor: "pointer" }}>
                    Log In
                  </a>
                </li>
              </>
            )}
          </ul>
        </div>
      </div>
    </nav>
  );
};
